import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Room devices and music","description":"","frontmatter":{},"headers":[],"relativePath":"features/devices-music.md","filePath":"features/devices-music.md","lastUpdated":1793092343000}'),i={name:"features/devices-music.md"};function d(r,e,c,n,l,h){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="room-devices-and-music" tabindex="-1">Room devices and music <a class="header-anchor" href="#room-devices-and-music" aria-label="Permalink to &quot;Room devices and music&quot;">​</a></h1><h2 id="the-room-s-devices" tabindex="-1">The room&#39;s devices <a class="header-anchor" href="#the-room-s-devices" aria-label="Permalink to &quot;The room&#39;s devices&quot;">​</a></h2><p>Each display belongs to a room (a Home Assistant area). Its buttons show the room&#39;s lights, switches, fans and media players, and the assistant can control <strong>only those</strong>: each request carries the room&#39;s devices, and the display only carries out actions on them.</p><table tabindex="0"><thead><tr><th>Action</th><th>For</th><th>With</th></tr></thead><tbody><tr><td><code>turn_on</code>, <code>turn_off</code>, <code>toggle</code></td><td>lights, switches, fans</td><td></td></tr><tr><td><code>brightness</code></td><td>lights</td><td><code>value</code> 0–100</td></tr><tr><td><code>media_play_pause</code>, <code>media_next_track</code></td><td>media players</td><td></td></tr><tr><td><code>volume</code></td><td>media players</td><td><code>value</code> 0–100</td></tr><tr><td><code>play_music</code></td><td>speakers that play music by name</td><td><code>query</code>, what to play</td></tr></tbody></table><p>Off with the grown-ups&#39; &quot;See and control the room&#39;s devices&quot; switch.</p><h2 id="music-by-name" tabindex="-1">Music by name <a class="header-anchor" href="#music-by-name" aria-label="Permalink to &quot;Music by name&quot;">​</a></h2><p>&quot;Play Sandstorm&quot;, &quot;put on some relaxing piano&quot;, &quot;play the Frozen soundtrack&quot;: <code>play_music</code> goes to a speaker in the display&#39;s room.</p><ul><li><strong>An Echo</strong> (Home Assistant&#39;s <a href="https://www.home-assistant.io/integrations/alexa_devices/" target="_blank" rel="noreferrer">Alexa Devices</a> integration) is told to play it from Spotify, by voice command, so it works without Spotify Premium.</li><li><strong>A <a href="https://www.music-assistant.io/" target="_blank" rel="noreferrer">Music Assistant</a> player</strong> gets <code>music_assistant.play_media</code>, which searches the music services you&#39;ve added to Music Assistant for the best match.</li></ul><p>The display marks such speakers &quot;plays music by name&quot; in the device list it sends, so the assistant knows where <code>play_music</code> works. Speech-to-text often mishears song names (&quot;Place and Storm&quot; for &quot;play Sandstorm&quot;), so the assistant makes its best guess and plays it, and they can just ask again.</p><p>Off with the grown-ups&#39; &quot;Play music&quot; switch.</p><div class="tip custom-block"><p class="custom-block-title">The speaker has to be in the room</p><p>A display only controls its own room&#39;s devices. To play music from the living room&#39;s display on a Music Assistant speaker, put that speaker&#39;s device in the living room area in Home Assistant.</p></div><p>To play a sound or a stream on the displays themselves, see <a href="/features/audio">Playing audio</a>.</p>',12)])])}const p=t(i,[["render",d]]);export{u as __pageData,p as default};
